+import { describe, expect, it, vi } from "vitest";
+import { createFetch } from "../src/fetch.ts";
+
+const breaker = {
+  threshold: 1,
+  cooldown: 100,
+  halfOpenMaxRequests: 1,
+};
+
+describe("circuit breaker", () => {
+  it("is opt-in and opens per effective origin after request hooks", async () => {
+    const fetch = vi.fn(async () => new Response("fail", { status: 500 }));
+    const $fetch = createFetch({ fetch });
+
+    await expect(
+      $fetch("/first", {
+        baseURL: "https://original.test",
+        circuitBreaker: breaker,
+        retry: false,
+        onRequest(context) {
+          context.request = "https://rewritten.test/first";
+        },
+      })
+    ).rejects.toThrow();
+
+    await expect(
+      $fetch(new URL("https://rewritten.test/second"), {
+        circuitBreaker: breaker,
+        retry: false,
+      })
+    ).rejects.toThrow("Circuit breaker is open");
+    expect(fetch).toHaveBeenCalledOnce();
+
+    await $fetch("https://other.test/", { retry: false }).catch(() => {});
+    expect(fetch).toHaveBeenCalledTimes(2);
+  });
+
+  it("shares state with clients created from a parent", async () => {
+    const fetch = vi.fn(async () => new Response("fail", { status: 500 }));
+    const parent = createFetch({ fetch });
+    const child = parent.create({});
+
+    await parent("https://shared.test/", {
+      circuitBreaker: breaker,
+      retry: false,
+    }).catch(() => {});
+    await expect(
+      child(new Request("https://shared.test/"), {
+        circuitBreaker: breaker,
+      })
+    ).rejects.toThrow("Circuit breaker is open");
+    expect(fetch).toHaveBeenCalledOnce();
+  });
+
