+    const response = await $fetch.raw("https://retry.test/", {
+      circuitBreaker: breaker,
+      retry: 1,
+      ignoreResponseError: true,
+    });
+    expect(response.status).toBe(500);
+    expect(fetch).toHaveBeenCalledOnce();
+
+    await expect(
+      $fetch("https://retry.test/", { circuitBreaker: breaker })
+    ).rejects.toThrow("Circuit breaker is open");
+  });
+
+  it("does not reset failures for non-listed rejected statuses", async () => {
