+
+    await $fetch("https://neutral.test/", options).catch(() => {});
+    await $fetch("https://neutral.test/", options).catch(() => {});
+    await $fetch("https://neutral.test/", options).catch(() => {});
+    await expect($fetch("https://neutral.test/", options)).rejects.toThrow(
+      "Circuit breaker is open"
+    );
+    expect(fetch).toHaveBeenCalledTimes(3);
