  if (input.startsWith(_base)) {
    return input;
  }

  return joinURL(_base, input);
}

function withoutTrailingSlash(path?: string): string {
  if (!path || path === "/") {
    return "/";
  }

  return path[path.length - 1] === "/" ? path.slice(0, -1) : path;
}

/**
